// Builds the generated parts of the app-dev-kitv2 factory plugins:
//   1. app-dev-kitv2/factory/scripts/vendor/deps.bundle.mjs — yaml, ajv, ajv-formats and picomatch in
//      one ESM file, so the engine runs without installing anything at session start.
//   2. <pack>/hooks/register.mjs + hooks.json + cursor-hooks.json for every non-engine pack, from one template.
//   node scripts/build-factory.mjs          regenerate
//   node scripts/build-factory.mjs --check  exit 1 when a generated file is out of date
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const family = join(root, "app-dev-kitv2");
const engine = join(family, "factory");
const check = process.argv.includes("--check");
const VENDORED = ["yaml", "ajv", "ajv-formats", "picomatch"];

let stale = 0;
function emit(path, content) {
  const rel = path.slice(root.length + 1);
  if (existsSync(path) && readFileSync(path, "utf8") === content) return;
  if (check) {
    console.error(`STALE: ${rel}`);
    stale++;
    return;
  }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
  console.log(`wrote ${rel}`);
}

async function vendorBundle() {
  const versions = VENDORED.map(
    (p) => `${p}@${JSON.parse(readFileSync(join(root, "node_modules", p, "package.json"), "utf8")).version}`,
  );
  const result = await build({
    stdin: {
      contents: [
        'export * as YAML from "yaml";',
        'export { default as Ajv } from "ajv";',
        'export { default as addFormats } from "ajv-formats";',
        'export { default as picomatch } from "picomatch";',
      ].join("\n"),
      resolveDir: root,
      loader: "js",
    },
    bundle: true,
    format: "esm",
    platform: "node",
    target: "node20",
    minify: true,
    legalComments: "none",
    // CommonJS deps call require("process") etc.; give the ESM bundle a real require.
    banner: { js: 'import { createRequire as __cr } from "node:module"; const require = __cr(import.meta.url);' },
    write: false,
  });
  const header = `// Generated by scripts/build-factory.mjs. Do not edit.\n// Bundles ${versions.join(", ")}.\n`;
  emit(join(engine, "scripts", "vendor", "deps.bundle.mjs"), header + result.outputFiles[0].text);
}

function packHooks() {
  const template = readFileSync(join(engine, "hooks", "register.mjs"), "utf8");
  const generated = template.replace(
    /^\/\/ TEMPLATE:.*\n/m,
    "// Generated by scripts/build-factory.mjs from factory/hooks/register.mjs. Do not edit.\n",
  );
  const hooks = {
    hooks: {
      SessionStart: [
        {
          hooks: [
            {
              type: "command",
              command:
                '[ -d "$CLAUDE_PROJECT_DIR/.factory" ] || exit 0; node "${CLAUDE_PLUGIN_ROOT}/hooks/register.mjs"',
              timeout: 10,
            },
          ],
        },
      ],
    },
  };
  // Cursor runs plugin hooks in its own format (camelCase events, CURSOR_PLUGIN_ROOT).
  const cursorHooks = {
    version: 1,
    hooks: {
      sessionStart: [
        {
          command:
            '[ -d "${CURSOR_PROJECT_DIR:-$CLAUDE_PROJECT_DIR}/.factory" ] || { echo \'{}\'; exit 0; }; node "${CURSOR_PLUGIN_ROOT}/hooks/register.mjs"; echo \'{}\'',
          timeout: 10,
        },
      ],
    },
  };
  for (const name of readdirSync(family)) {
    const pack = join(family, name);
    if (name === "factory" || !existsSync(join(pack, ".claude-plugin", "plugin.json"))) continue;
    emit(join(pack, "hooks", "register.mjs"), generated);
    emit(join(pack, "hooks", "hooks.json"), `${JSON.stringify(hooks, null, 2)}\n`);
    emit(join(pack, "hooks", "cursor-hooks.json"), `${JSON.stringify(cursorHooks, null, 2)}\n`);
  }
}

await vendorBundle();
packHooks();
if (stale) {
  console.error(`${stale} generated factory file(s) out of date. Run: npm run build:factory`);
  process.exit(1);
}
if (check) console.log("OK: factory generated files up to date");
